DOCUMENT();

#############
# Load Macros
#############

loadMacros(
  "PGstandard.pl",
  "PGML.pl",
  "AnswerFormatHelp.pl",
  "PGlateximage.pl",
  "PCCmacros.pl",
  "ORCCA.pl",
  "PGcourse.pl",
);
COMMENT('Authored in PreTeXt');

#######
# Setup
#######

@xy = random_subset(8, -4..-1, 1..4);
@x = (@xy)[0..3];
@y = (@xy)[4..7];
@z = random_subset(2,0..3);
$x[$z[0]] = 0;
$y[$z[1]] = 0;
Context("Point");
@p = map {Point($x[$_], $y[$_])} (0..3);
@absx = map {abs($_)} @x;
@absy = map {abs($_)} @y;
@dirx = map {($_ >= 0) ? 'to the right' : 'to the left'} @x;
@diry = map {($_ >= 0) ? 'up' : 'down'} @y;

$image_1 = createLaTeXImage();
$image_1->addToPreamble(latexImagePreamble());
$image_1->BEGIN_LATEX_IMAGE
\begin{tikzpicture}
  \begin{axis}[
      width=0.47\orccaprintwidth,
    ]
    \addplot[soliddot] coordinates {$p[0]} node[pin=60:{A}] {};
    \addplot[soliddot] coordinates {$p[1]} node[pin=60:{B}] {};
    \addplot[soliddot] coordinates {$p[2]} node[pin=60:{C}] {};
    \addplot[soliddot] coordinates {$p[3]} node[pin=60:{D}] {};
  \end{axis}
\end{tikzpicture}

END_LATEX_IMAGE

######
# Body
######

BEGIN_PGML
>> [@image(insertGraph($image_1), width=>282)@]*  <<

[@KeyboardInstructions('The coordinates of [`A`] are:')@]**

[_]{$p[0]}{3}

[@KeyboardInstructions('The coordinates of [`B`] are:')@]**

[_]{$p[1]}{3}

[@KeyboardInstructions('The coordinates of [`C`] are:')@]**

[_]{$p[2]}{3}

[@KeyboardInstructions('The coordinates of [`D`] are:')@]**

[_]{$p[3]}{3}

END_PGML

##########
# Solution
##########

BEGIN_PGML_SOLUTION
Point [`A`] is [`[$absx[0]]`] [$dirx[0]] and [`[$absy[0]]`] [$diry[0]] from the origin, so its coordinates are [`[$p[0]]\text{.}`]

Point [`B`] is [`[$absx[1]]`] [$dirx[1]] and [`[$absy[1]]`] [$diry[1]] from the origin, so its coordinates are [`[$p[1]]\text{.}`]

Point [`C`] is [`[$absx[2]]`] [$dirx[2]] and [`[$absy[2]]`] [$diry[2]] from the origin, so its coordinates are [`[$p[2]]\text{.}`]

Point [`D`] is [`[$absx[3]]`] [$dirx[3]] and [`[$absy[3]]`] [$diry[3]] from the origin, so its coordinates are [`[$p[3]]\text{.}`]

END_PGML_SOLUTION

